        .is_some_and(|sequence| sequence.bytes.is_empty());
    if should_finish {
        let sequence = self
            .escape_sequence
            .take()
            .expect("escape sequence is present");
        self.dispatch_pending_escape_if_needed(&sequence);
    }
}

